const orders = [
  { id: 'BB-20261112-001', status: 'processing', createdAt: '2026-11-12T08:30:00.000Z', currency: 'USD', customer: { fullName: 'Sofia Lin', email: 'sofia@example.com', country: 'United States', address1: '468 Market Street', address2: 'Apt 12B', city: 'San Francisco', region: 'CA', postalCode: '94105', phone: '+1 415 555 0188' }, items: [{ productId: 'p-101', name: '晨雾竹篮', quantity: 1, price: 48 }, { productId: 'p-105', name: '一方竹托', quantity: 2, price: 28 }], subtotal: 104, shipping: 0, total: 104 }
];

function json(data, status = 200) {
  return new Response(JSON.stringify(data), { status, headers: { 'content-type': 'application/json; charset=UTF-8', 'cache-control': 'no-store' } });
}

function withCors(response) {
  const headers = new Headers(response.headers);
  headers.set('access-control-allow-origin', '*');
  headers.set('access-control-allow-headers', 'content-type, x-admin-token');
  headers.set('access-control-allow-methods', 'GET, POST, PUT, DELETE, OPTIONS');
  return new Response(response.body, { status: response.status, headers });
}

function adminAllowed(request) {
  return request.headers.get('x-admin-token') === ADMIN_TOKEN;
}

async function readBody(request) {
  try { return await request.json(); } catch (_) { return null; }
}

function newOrderId() {
  return 'BB-' + new Date().toISOString().slice(0, 10).replaceAll('-', '') + '-' + String(orders.length + 1).padStart(3, '0');
}

async function api(request, env) {
  const url = new URL(request.url);
  const path = url.pathname;
  if (request.method === 'OPTIONS') return withCors(new Response(null, { status: 204 }));

  if (path === '/api/health' && request.method === 'GET') return withCors(json({ ok: true, service: 'bamboo-basket-api', backend: 'connected' }));
  if (path === '/api/products' && request.method === 'GET') return withCors(json({ products }));

  if (path === '/api/auth/social' && request.method === 'POST') {
    const body = await readBody(request);
    if (!body || !SOCIAL_PROVIDERS.includes(body.provider)) return withCors(json({ error: 'Unsupported provider' }, 400));
    return withCors(json({ ok: true, provider: body.provider, user: { id: body.provider + '-demo-user', name: body.provider === 'apple' ? 'Apple shopper' : 'Google shopper', email: body.provider + '.shopper@example.com' }, token: body.provider + '-demo-session' }));
  }

  if (path === '/api/admin/login' && request.method === 'POST') {
    const body = await readBody(request);
    if (body && body.email === 'admin@zhuliji.com' && body.password === 'bamboo2026') return withCors(json({ ok: true, token: ADMIN_TOKEN, admin: { name: '竹里集管理员', email: body.email } }));
    return withCors(json({ error: '邮箱或密码不正确' }, 401));
  }

  if (path === '/api/orders' && request.method === 'POST') {
    const body = await readBody(request);
    const customer = body && body.customer;
    if (!customer || !customer.fullName || !customer.email || !customer.country || !customer.address1 || !customer.city || !customer.region || !customer.postalCode || !customer.phone) return withCors(json({ error: '请完整填写国际收货地址与联系方式' }, 400));
    const items = Array.isArray(body.items) ? body.items : [];
    if (!items.length) return withCors(json({ error: '购物车为空' }, 400));
    const lineItems = items.map(function(item) { const p = products.find(function(product) { return product.id === item.productId; }); return p ? { productId: p.id, name: p.name, quantity: Math.max(1, Number(item.quantity) || 1), price: p.price } : null; }).filter(Boolean);
    const subtotal = lineItems.reduce(function(sum, item) { return sum + item.price * item.quantity; }, 0);
    const shipping = subtotal >= 99 ? 0 : 12.9;
    const order = { id: newOrderId(), status: 'processing', createdAt: new Date().toISOString(), currency: 'USD', customer: { fullName: customer.fullName, email: customer.email, country: customer.country, address1: customer.address1, address2: customer.address2 || '', city: customer.city, region: customer.region, postalCode: customer.postalCode, phone: customer.phone }, items: lineItems, subtotal: Number(subtotal.toFixed(2)), shipping, total: Number((subtotal + shipping).toFixed(2)) };
    orders.unshift(order);
    return withCors(json({ ok: true, order }, 201));
  }

  if (path === '/api/orders' && request.method === 'GET') {
    if (!adminAllowed(request)) return withCors(json({ error: 'Admin authorization required' }, 401));
    return withCors(json({ orders }));
  }

  const productMatch = path.match(/^\/api\/products\/([^/]+)$/);
  if (productMatch) {
    if (!adminAllowed(request)) return withCors(json({ error: 'Admin authorization required' }, 401));
    const index = products.findIndex(function(p) { return p.id === productMatch[1]; });
    if (request.method === 'DELETE') {
      if (index < 0) return withCors(json({ error: 'Product not found' }, 404));
      products.splice(index, 1);
      return withCors(json({ ok: true }));
    }
    if (request.method === 'PUT') {
      if (index < 0) return withCors(json({ error: 'Product not found' }, 404));
      const body = await readBody(request) || {};
      products[index] = { ...products[index], name: body.name || products[index].name, category: body.category || products[index].category, description: body.description || products[index].description, price: Number(body.price) || products[index].price, stock: Number(body.stock) >= 0 ? Number(body.stock) : products[index].stock, badge: body.badge || products[index].badge, translations: body.translations || products[index].translations };
      return withCors(json({ ok: true, product: products[index] }));
    }
  }

  if (path === '/api/products' && request.method === 'POST') {
    if (!adminAllowed(request)) return withCors(json({ error: 'Admin authorization required' }, 401));
    const body = await readBody(request) || {};
    if (!body.name || !body.price) return withCors(json({ error: '商品名称和价格必填' }, 400));
    const defaultName = body.name || (body.translations && body.translations.zh && body.translations.zh.name) || '未命名商品';
    const defaultDescription = body.description || (body.translations && body.translations.zh && body.translations.zh.description) || '手工竹编，来自自然的日常。';
    const product = { id: 'p-' + Date.now(), name: defaultName, category: body.category || '家居', description: defaultDescription, price: Number(body.price), compareAt: Number(body.price) + 8, badge: body.badge || 'New', color: '#b7c89a', icon: '🎋', stock: Number(body.stock) || 0, translations: body.translations || { zh: { name: defaultName, description: defaultDescription }, en: { name: body.nameEn || defaultName, description: body.descriptionEn || defaultDescription }, de: { name: body.nameDe || defaultName, description: body.descriptionDe || defaultDescription }, it: { name: body.nameIt || defaultName, description: body.descriptionIt || defaultDescription } } };
    products.unshift(product);
    return withCors(json({ ok: true, product }, 201));
  }

  const orderMatch = path.match(/^\/api\/orders\/([^/]+)$/);
  if (orderMatch && request.method === 'PUT') {
    if (!adminAllowed(request)) return withCors(json({ error: 'Admin authorization required' }, 401));
    const order = orders.find(function(o) { return o.id === orderMatch[1]; });
    if (!order) return withCors(json({ error: 'Order not found' }, 404));
    const body = await readBody(request) || {};
    if (!['processing', 'paid', 'shipped', 'delivered', 'cancelled'].includes(body.status)) return withCors(json({ error: 'Invalid status' }, 400));
    order.status = body.status;
    return withCors(json({ ok: true, order }));
  }

  return withCors(json({ error: 'Not found' }, 404));
}

