    document.getElementById('cart-trigger').onclick=function(){renderCart();openModal('cart-drawer')};
    document.getElementById('cart-backdrop').onclick=function(){closeModal('cart-drawer')};
    document.getElementById('cart-close').onclick=function(){closeModal('cart-drawer')};
