    document.getElementById('story-trigger').onclick=function(){document.getElementById('story').scrollIntoView()};
    document.querySelectorAll('[data-close]').forEach(function(btn){btn.onclick=function(){closeModal(btn.getAttribute('data-close'))}});
    document.querySelectorAll('[data-social]').forEach(function(btn){btn.onclick=function(){var provider=btn.getAttribute('data-social'); btn.disabled=true; api('/api/auth/social',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({provider:provider})}).then(function(data){state.user=data.user;localStorage.setItem('bamboo-user',JSON.stringify(state.user));closeModal('login-modal');renderHome();toast('已使用 '+(provider==='apple'?'Apple':'Google')+' 登录')}).catch(function(err){toast(err.message)}).finally(function(){btn.disabled=false})}});
